  // valid fixed zones still work
  expect(DateTime.fromMillis(0, { zone: FixedOffsetZone.instance(300) }).isValid).toBe(true);
  expect(DateTime.fromMillis(0, { zone: "utc" }).isValid).toBe(true);
  expect(DateTime.fromMillis(0, { zone: "UTC+5" }).isValid).toBe(true);
  expect(DateTime.fromMillis(0, { zone: "UTC+5" }).offset).toBe(300);
